package com.petplan.service;
import com.petplan.repository.Datos; import com.petplan.service.CuentaService.Actor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import static com.petplan.service.Reglas.*; import static com.petplan.service.CuentaService.*;
@Service public class ClinicaService {
 private final Datos db; private final VeterinariaService vet;
 public ClinicaService(Datos db,VeterinariaService vet){this.db=db;this.vet=vet;}
 private static final String CITAS="SELECT c.codigo_cita,c.tipo_cita,c.descripcion,c.fecha,c.confirmacion,c.codigo_veterinarias,v.nombre veterinaria FROM cita c JOIN veterinarias v ON v.codigo_veterinarias=c.codigo_veterinarias WHERE ";
 public List<Map<String,Object>> citas(Actor a,Map<String,String> f){a.exige(USUARIO,VET,ADMIN);List<Object> args=new ArrayList<>();String where;if(a.rol().equals(USUARIO)){where="EXISTS(SELECT 1 FROM usuario_cita uc WHERE uc.codigo_cita=c.codigo_cita AND uc.codigo_usuario=?)";args.add(a.id());}else{where="c.codigo_veterinarias=?";args.add(vet.clinica(a));}if(f.get("desde")!=null&&!f.get("desde").isBlank()){where+=" AND c.fecha>=?";args.add(fecha(f.get("desde")).atStartOfDay());}if(f.get("hasta")!=null&&!f.get("hasta").isBlank()){where+=" AND c.fecha<?";args.add(fecha(f.get("hasta")).plusDays(1).atStartOfDay());}if(f.get("estado")!=null&&!f.get("estado").isBlank()){where+=switch(f.get("estado")){case "Pendiente"->" AND c.confirmacion=FALSE";case "Confirmada"->" AND c.confirmacion=TRUE";default->throw invalido("Estado inválido");};}if(f.get("veterinaria")!=null&&!f.get("veterinaria").isBlank()){where+=" AND c.codigo_veterinarias=?";args.add(id(f.get("veterinaria")));}return db.lista(CITAS+where+" ORDER BY c.fecha DESC",args.toArray());}
 public Map<String,Object> cita(Actor a,long id){return citas(a,Map.of()).stream().filter(c->n(c,"codigo_cita")==id).findFirst().orElseThrow(()->noEncontrado("Cita no encontrada"));}
 private LocalDateTime fechaCita(Map<String,Object>d){try{var f=LocalDateTime.parse(texto(d,"fecha",30,true));if(!f.isAfter(LocalDateTime.now()))throw invalido("La cita debe ser futura");return f;}catch(java.time.format.DateTimeParseException e){throw invalido("Fecha y hora inválidas");}}
 @Transactional public long agendar(Actor a,Map<String,Object>d){a.exige(USUARIO);long c=id(d.get("codigo_veterinarias"));vet.aprobada(c);db.uno("SELECT codigo_usuario FROM usuario WHERE codigo_usuario=? FOR UPDATE",a.id());var f=fechaCita(d);duplicada(a.id(),f,0);long id=db.insertar("INSERT INTO cita(tipo_cita,descripcion,fecha,codigo_veterinarias) VALUES(?,?,?,?)",texto(d,"tipo_cita",50,true),texto(d,"descripcion",5000,false),f,c);db.cambiar("INSERT INTO usuario_cita(codigo_usuario,codigo_cita) VALUES(?,?)",a.id(),id);return id;}
 private void duplicada(long u,LocalDateTime f,long excepto){if(!db.lista("SELECT c.codigo_cita FROM cita c JOIN usuario_cita uc ON uc.codigo_cita=c.codigo_cita WHERE uc.codigo_usuario=? AND c.fecha=? AND c.codigo_cita<>?",u,f,excepto).isEmpty())throw conflicto("Ya existe una cita en esa fecha");}
 @Transactional public void reprogramar(Actor a,long id,Map<String,Object>d){a.exige(USUARIO);db.uno("SELECT codigo_usuario FROM usuario WHERE codigo_usuario=? FOR UPDATE",a.id());var r=cita(a,id);if(si(r.get("confirmacion")))throw conflicto("Cita confirmada");if(db.lista("SELECT codigo_usuario FROM usuario_cita WHERE codigo_cita=?",id).size()!=1)throw conflicto("Cita compartida: no se puede reprogramar individualmente");var f=fechaCita(d);duplicada(a.id(),f,id);if(db.cambiar("UPDATE cita SET fecha=? WHERE codigo_cita=? AND confirmacion=FALSE",f,id)==0)throw conflicto("Cita confirmada");}
 @Transactional public void cancelar(Actor a,long id){a.exige(USUARIO);db.uno("SELECT codigo_usuario FROM usuario WHERE codigo_usuario=? FOR UPDATE",a.id());var r=cita(a,id);if(si(r.get("confirmacion")))throw conflicto("No se puede eliminar una cita confirmada");db.uno("SELECT codigo_cita FROM cita WHERE codigo_cita=? AND confirmacion=FALSE FOR UPDATE",id);if(db.lista("SELECT codigo_usuario FROM usuario_cita WHERE codigo_cita=?",id).size()!=1)throw conflicto("Cita compartida: no se puede eliminar individualmente");db.cambiar("DELETE FROM cita WHERE codigo_cita=? AND confirmacion=FALSE",id);}
 @Transactional public void confirmar(Actor a,long id){a.exige(VET);cita(a,id);db.cambiar("UPDATE cita SET confirmacion=TRUE WHERE codigo_cita=?",id);}
}
